parameters.jsCode:
/**
 * Extracts and normalises the email data from the Microsoft Outlook trigger.
 * Strips HTML, decodes entities, returns the fields needed downstream.
 */

const m = $input.item.json;

const fromEmail = m?.sender?.emailAddress?.address || "";
const fromName = m?.sender?.emailAddress?.name || fromEmail || "Unknown";
const subject = m?.subject || "(no subject)";
const messageId = m?.id || "";
const receivedAt = m?.receivedDateTime || new Date().toISOString();

const rawBody = m?.body?.content || m?.bodyPreview || "";
const contentType = m?.body?.contentType || "text";

const plainBody = contentType === "html"
  ? rawBody
      .replace(/<style[\s\S]*?<\/style>/gi, "")
      .replace(/<script[\s\S]*?<\/script>/gi, "")
      .replace(/<br\s*\/?>/gi, "\n")
      .replace(/<\/p>/gi, "\n\n")
      .replace(/<[^>]+>/g, "")
      .replace(/&nbsp;/gi, " ")
      .replace(/&amp;/gi, "&")
      .replace(/&lt;/gi, "<")
      .replace(/&gt;/gi, ">")
      .replace(/&quot;/gi, '"')
      .replace(/&#39;/gi, "'")
      .replace(/\n{3,}/g, "\n\n")
      .trim()
  : rawBody.trim();

return {
  json: {
    fromEmail,
    fromName,
    subject,
    plainBody,
    messageId,
    receivedAt,
    aiInputText: `Betreff: ${subject}\n\nAbsender: ${fromName} <${fromEmail}>\n\nNachricht:\n${plainBody}`,
  },
};

/**
 * Baut das fertige Task-Objekt aus den vorigen Knoten:
 * - Direkter Vorgaenger (OpenAI) liefert title/category/priority/dueDate/description
 * - "Code in JavaScript" liefert die Email-Rohdaten (fromEmail, messageId etc.)
 */

const aiResponse = $input.first().json;
const email = $('Code in JavaScript').first().json;

// AI-Output liegt unter output[0].content[0].text und kann Objekt oder JSON-String sein
let ai = aiResponse?.output?.[0]?.content?.[0]?.text;
if (typeof ai === 'string') {
  try { ai = JSON.parse(ai); } catch (_e) { ai = {}; }
}
ai = ai || {};

const creator = {
  email: email.fromEmail || '',
  name: email.fromName || email.fromEmail || 'External',
  type: 'external',
};

const aiNote = '\n\n---\nDieses Ticket wurde KI-generiert basierend auf einer E-Mail-Anfrage von ' + (email.fromEmail || 'unbekannt');

const payload = {
  title: (ai.title && ai.title.trim()) || email.subject || 'Neues Feature Request',
  description: (ai.description || email.plainBody || '') + aiNote,
  dueDate: ai.dueDate || '',
  priority: ['Urgent', 'Medium', 'Low'].includes(ai.priority) ? ai.priority : 'Medium',
  category: ['Technical Tasks', 'User Story'].includes(ai.category) ? ai.category : 'User Story',
  assignedTo: [],
  subtasks: [],
  status: 'triage',
  creator,
  aiGenerated: true,
  createdAt: new Date().toISOString(),
};

return {
  json: {
    payload,
    meta: {
      messageId: email.messageId,
      fromEmail: email.fromEmail,
      fromName: email.fromName,
      ticketTitle: payload.title,
    },
  },
};

